#include <queue>
#include <iostream>

struct Task { int id; bool processed = false; };

int main() {
    std::queue<Task> tasks;
    tasks.push({101, false});

    // Modify the element while it is in the queue
    tasks.back().id = 202; 
    tasks.front().processed = true; 

    // Verify modification
    std::cout << "Front ID: " << tasks.front().id 
              << ", Processed: " << tasks.front().processed << "\n";
    tasks.pop();
}
